from structure import C,E

C('Mesurer et raisonner','mesure',[
'Choisir les unités et donner un ordre de grandeur.',
'Interpréter la dispersion de mesures indépendantes.',
'Présenter un résultat et discuter sa compatibilité avec une référence.'],[
('Une grandeur, un nombre et une unité',r'''Une mesure associe une valeur à une grandeur : longueur, durée, masse, température. Écrire « 12 » ne suffit pas à décrire une longueur. Le symbole de l'unité ne prend pas de pluriel. Avant un calcul, choisir un ensemble cohérent d'unités.
\begin{definition}[Écriture scientifique]Un nombre positif s'écrit $a\times10^p$ avec $1\leq a<10$ et $p$ entier. Les préfixes milli, micro et nano correspondent à $10^{-3}$, $10^{-6}$ et $10^{-9}$.\end{definition}
Un ordre de grandeur sert à repérer un résultat invraisemblable. Une règle graduée au millimètre ne permet pas, à elle seule, de distinguer des longueurs au micromètre.
\begin{exemple}[Convertir avant de diviser]$V=\qty{25,0}{mL}=\qty{0,0250}{L}$ ; $m=\qty{0,450}{g}$. Le quotient $m/V$ vaut $\qty{18,0}{g.L^{-1}}$.\end{exemple}'''),
('Mesures répétées et dispersion',r'''Même avec le même protocole, des mesures indépendantes diffèrent légèrement : lecture, remplissage, environnement. Refaire le même calcul sur la même mesure ne constitue pas une nouvelle mesure indépendante.
\begin{definition}[Moyenne et écart-type]La moyenne $\bar x$ situe la série. L'écart-type expérimental $s$ décrit sa dispersion. Un histogramme rassemble les valeurs par intervalles ; sa forme dépend aussi du choix de ces intervalles.\end{definition}
Pour $N$ mesures indépendantes réalisées dans les mêmes conditions, on peut estimer l'incertitude-type sur la moyenne par $u(\bar x)=s/\sqrt N$. L'écart-type $s$ concerne la dispersion des valeurs individuelles ; il ne faut pas le confondre avec $u(\bar x)$.
\schema{histogramme}'''),
('Écrire et discuter un résultat',r'''On conserve des chiffres pendant le calcul, puis on arrondit le résultat final. Lorsqu'une incertitude est donnée, la valeur et l'incertitude s'écrivent au même rang décimal.
\begin{exemple}[Une conclusion mesurée]Pour $\bar V=\qty{10,03}{mL}$ et $u(\bar V)=\qty{0,02}{mL}$, écrire ces deux valeurs avec leur unité. Une référence de \qty{10,00}{mL} est proche à l'échelle de quelques incertitudes-types ; une référence de \qty{10,50}{mL} est nettement éloignée. En Seconde, on discute qualitativement cette comparaison.\end{exemple}
\begin{attention}[Ce qu'une répétition ne corrige pas]Une balance mal réglée peut décaler toute une série. Répéter réduit l'effet des fluctuations sur la moyenne, mais ne supprime pas ce décalage. Une incertitude-type n'est pas une borne absolue de l'erreur.\end{attention}''')],
r'''\begin{experience}[Comparer deux verreries]Peser l'eau délivrée par une éprouvette puis par une pipette, après tare du récipient. Recommencer dix fois en vidant et remplissant à nouveau. À température donnée, convertir les masses en volumes avec la masse volumique fournie. Comparer les moyennes et les dispersions, puis discuter le choix de la verrerie.\end{experience}
\begin{savoirfaire}[Tableur]Saisir une mesure par cellule. Calculer la moyenne et l'écart-type d'échantillon, choisir des classes contiguës et de même largeur, puis produire l'histogramme. L'axe horizontal porte la grandeur et l'unité ; l'axe vertical porte l'effectif. Ne pas relier les barres comme une trajectoire.\end{savoirfaire}''',[
E('Changer de préfixe',r'Un capteur détecte un déplacement de \qty{450}{\micro m} et une durée de \qty{2,5}{ms}.',[r'Exprimer ces deux valeurs dans les unités SI.',r'Écrire \qty{0,000072}{m} en écriture scientifique.'],[r'$d=\qty{4,50e-4}{m}$ et $\Delta t=\qty{2,5e-3}{s}$. On applique les facteurs $10^{-6}$ et $10^{-3}$.',r'$\qty{7,2e-5}{m}$ : la mantisse est comprise entre 1 et 10.']),
E('Un résultat sans unité',r'Une élève écrit : « Le volume vaut 25 et la masse 19,8 g ».',[r'Pourquoi le premier résultat est-il incomplet ?',r'Compléter si le volume a été lu en millilitres et convertir en litres.'],[r'Le nombre 25 ne précise pas l’unité de volume ; 25 mL et 25 L décrivent des quantités différentes.',r'$V=\qty{25}{mL}=\qty{0,025}{L}$.']),
E('Lire un instrument',r'Une règle porte des traits espacés de \qty{1}{mm}. On mesure une longueur proche de \qty{8,4}{cm}.',[r'Choisir entre 8,4 cm et 8,40000 cm pour rendre compte de cette lecture.',r'Citer deux causes possibles de variation entre lectures.'],[r'8,4 cm est une écriture cohérente avec le millimètre. Les zéros supplémentaires annonceraient une précision non justifiée.',r'Le positionnement du zéro et l’angle d’observation peuvent modifier la lecture.']),
E('Une moyenne simple',r'Quatre durées indépendantes valent 2,1 ; 2,0 ; 2,2 ; 2,1 s.',[r'Calculer la moyenne.',r'Pourquoi ne faut-il pas supprimer 2,2 s uniquement parce que cette valeur est la plus grande ?'],[r'$\bar t=(2,1+2,0+2,2+2,1)/4=\qty{2,1}{s}$.',r'Une fluctuation est attendue. Une suppression demande une cause identifiée, par exemple un déclenchement raté, et doit être documentée.']),
E('Deux distributions',r'La figure présente deux séries de mesures d’un volume nominal de \qty{10,0}{mL}.',[r'Quelle série est la moins dispersée ?',r'Une faible dispersion garantit-elle l’absence de décalage systématique ?'],[r'La série A est la plus resserrée autour de 10,0 mL.',r'Non. Des valeurs peuvent être très regroupées autour d’une valeur décalée ; il faut également vérifier l’instrument et comparer à une référence.'],'histogramme'),
E('Estimer une incertitude',r'Pour 16 mesures indépendantes, on obtient $\bar V=\qty{24,96}{mL}$ et $s=\qty{0,12}{mL}$.',[r'Calculer $u(\bar V)=s/\sqrt N$.',r'Présenter la moyenne et son incertitude-type.'],[r'$u=0,12/4=\qty{0,03}{mL}$.',r'$\bar V=\qty{24,96}{mL}$ et $u(\bar V)=\qty{0,03}{mL}$. Les deux écritures vont au centième.']),
E('Arrondir à la fin',r'On calcule $v=0,625/0,48$ en unités SI.',[r'Calculer sans arrondir les étapes intermédiaires.',r'Proposer une écriture à deux chiffres significatifs.'],[r'La calculatrice donne $v=1,302083\ldots\unit{m.s^{-1}}$.',r'$v=\qty{1,3}{m.s^{-1}}$ ; la durée comporte deux chiffres significatifs.']),
E('Comparer à une référence',r'Un groupe obtient $\bar \rho=\qty{0,79}{g.mL^{-1}}$, avec $u=\qty{0,01}{g.mL^{-1}}$. Deux références sont 0,789 et \qty{1,00}{g.mL^{-1}}.',[r'Laquelle paraît compatible à l’échelle de l’incertitude ?',r'Pourquoi cela ne prouve-t-il pas l’identité du liquide ?'],[r'0,789 est très proche de 0,79 ; 1,00 est éloigné de 0,21, soit 21 fois l’incertitude annoncée.',r'Des espèces ou des mélanges peuvent avoir des masses volumiques proches. Il faut croiser plusieurs indices.']),
E('Un quotient trompeur',r'Un calcul donne $m/V=250/0,50=500$ à partir de $m=\qty{250}{mg}$ et $V=\qty{0,50}{L}$.',[r'Associer l’unité correcte à 500.',r'Exprimer le résultat en \unit{g.L^{-1}}.'],[r'$500\unit{mg.L^{-1}}$ car la masse a été saisie en milligrammes.',r'$\qty{0,50}{g.L^{-1}}$. Convertir l’unité ne change pas la grandeur physique.']),
E('Répéter utilement',r'Deux élèves disposent de la même mesure de masse. Le premier la saisit dix fois ; le second effectue dix nouvelles pesées après avoir vidé puis rempli le récipient.',[r'Quelle démarche permet d’étudier la variabilité du remplissage ?',r'Le second doit-il conserver la tare et la température sous contrôle ?'],[r'La seconde : elle produit des mesures indépendantes du volume délivré. Recopier une valeur ne crée aucune information nouvelle.',r'Oui. Il faut maîtriser les conditions qui affectent la masse mesurée pour interpréter la dispersion.']),
E('Améliorer une méthode',r'On chronomètre à la main une seule oscillation de durée proche de 0,8 s. Le temps de réaction gêne la mesure.',[r'Proposer une méthode avec le même chronomètre.',r'Dix oscillations durent 8,16 s ; déterminer la période moyenne.'],[r'Chronométrer plusieurs oscillations puis diviser par leur nombre ; répéter la manipulation. Le délai de réaction pèse moins sur une durée plus longue.',r'$T=8,16/10=\qty{0,816}{s}$ avant choix de l’arrondi selon l’incertitude.']),
E('Histogramme et classes',r'On mesure 9,8 ; 9,9 ; 10,0 ; 10,0 ; 10,1 ; 10,2 mL. Les classes sont $[9,75;9,95[$, $[9,95;10,15[$ et $[10,15;10,35]$.',[r'Donner les trois effectifs.',r'Calculer la moyenne et expliquer ce que l’histogramme apporte de plus.'],[r'Les effectifs sont 2, 3 et 1. Chaque valeur est comptée une seule fois.',r'$\bar V=\qty{10,0}{mL}$. L’histogramme montre la répartition et la dispersion que la moyenne seule ne décrit pas.'])],
E('Deux laboratoires',r'Les laboratoires A et B mesurent la même longueur. A : $\bar L=\qty{50,12}{mm}$, $s=\qty{0,08}{mm}$, $N=16$. B : $\bar L=\qty{50,10}{mm}$, $s=\qty{0,12}{mm}$, $N=36$. La référence est \qty{50,00}{mm}.',[r'Calculer les deux incertitudes-types sur la moyenne.',r'Comparer les dispersions individuelles puis les incertitudes sur la moyenne.',r'Que suggère le décalage commun par rapport à la référence ?'],[r'$u_A=0,08/4=\qty{0,02}{mm}$ ; $u_B=0,12/6=\qty{0,02}{mm}$.',r'B a des mesures individuelles plus dispersées, mais ses mesures plus nombreuses conduisent ici à la même incertitude sur la moyenne.',r'Les écarts de 0,12 et 0,10 mm dépassent nettement les incertitudes annoncées. Rechercher une origine commune : étalonnage ou protocole. La répétition ne suffit pas à la corriger.'],methode=r'Piste 1 : séparer $s$ et $u$. Piste 2 : utiliser les racines de 16 et 36. Piste 3 : examiner la référence après les calculs.',note=r'La qualité d’une mesure dépend à la fois de sa dispersion et de la maîtrise des décalages systématiques.'),
['Unités et puissances de dix','Histogramme, moyenne, écart-type','Incertitude-type statistique','Chiffres significatifs et comparaison qualitative'])

C('Identifier la matière','molecules',[
'Distinguer corps pur et mélange, espèce et échantillon.',
'Croiser tests chimiques, masse volumique et chromatographie.',
'Calculer une composition massique ou volumique.'],[
('Corps purs et mélanges',r'''Un échantillon est une portion de matière. Une espèce chimique correspond à un ensemble d'entités identiques. Un corps pur ne contient qu'une espèce ; un mélange en contient plusieurs. Un mélange homogène présente une seule phase observable à l'échelle choisie. Un liquide transparent peut donc être un mélange.
\begin{exemple}L'eau salée limpide est homogène ; l'eau et l'huile non miscibles forment deux phases après décantation. L'air est un mélange gazeux : environ 78 \% de diazote, 21 \% de dioxygène et 1 \% d'autres gaz en volume.\end{exemple}'''),
('Masse volumique et composition',r'''\begin{definition}[Une propriété de l'échantillon]$\rho=m/V$. Avec $m$ en kilogrammes et $V$ en mètres cubes, $\rho$ s'exprime en \unit{kg.m^{-3}}. L'eau liquide vaut environ \qty{1,00}{g.mL^{-1}}, soit \qty{1,00e3}{kg.m^{-3}} ; l'air est de l'ordre de \qty{1}{kg.m^{-3}}. Les valeurs dépendent des conditions.\end{definition}
La fraction massique d'une espèce est $w=m_{\mathrm{espèce}}/m_{\mathrm{mélange}}$ ; le pourcentage vaut $100w$. Les fractions de toutes les espèces somment à 1. Les volumes de liquides mélangés ne sont pas toujours additifs.
\schema{densite}'''),
('Identifier avec plusieurs indices',r'''Le sulfate de cuivre anhydre blanc devient bleu en présence d'eau. Le dioxyde de carbone trouble l'eau de chaux ; le dioxygène ravive une bûchette incandescente ; une très petite quantité de dihydrogène donne une détonation caractéristique au contact d'une flamme. Ces tests relèvent du laboratoire encadré.
\begin{savoirfaire}[Lire une CCM]Déposer les échantillons sur la ligne de dépôt, au-dessus de l'éluant ; fermer la cuve ; laisser monter l'éluant ; sortir la plaque et repérer le front. Plusieurs taches dans une piste révèlent plusieurs espèces détectées. Une tache à même hauteur qu'une référence, dans les mêmes conditions, est un indice d'identité.\end{savoirfaire}
\schema{ccm-identification}
Une température de changement d'état ou une masse volumique proche d'une référence ne suffit pas toujours à identifier une espèce sans ambiguïté.''')],
r'''\begin{experience}[Identifier un liquide]Peser un récipient vide puis le même récipient contenant un volume connu de liquide ; soustraire les masses. Comparer la masse volumique à une table à la même température. Compléter par un test ou une mesure de température de changement d'état. Porter blouse et lunettes ; ne pas goûter ni sentir directement les produits.\end{experience}''',[
E('Trier des échantillons',r'On dispose de cuivre pur, d’eau sucrée limpide et d’eau mêlée à de l’huile.',[r'Classer ces trois échantillons.',r'La transparence garantit-elle la pureté ?'],[r'Cuivre : corps pur ; eau sucrée : mélange homogène ; eau-huile : mélange hétérogène après décantation.',r'Non, le sucre dissous reste présent même si on ne voit pas ses entités.']),
E('Mesurer une masse volumique',r'Le récipient vide pèse 42,6 g ; rempli de 20,0 mL d’un liquide, il pèse 58,4 g.',[r'Calculer la masse du liquide.',r'Calculer sa masse volumique.'],[r'$m=58,4-42,6=\qty{15,8}{g}$.',r'$\rho=15,8/20,0=\qty{0,790}{g.mL^{-1}}$.'],'densite'),
E('Reconnaître un gaz',r'Un gaz recueilli lors d’une réaction trouble l’eau de chaux.',[r'Quelle espèce est mise en évidence ?',r'Quel test distinguerait le dioxygène ?'],[r'Le dioxyde de carbone, \ce{CO2}.',r'Le dioxygène ravive une bûchette incandescente, dans un test encadré au laboratoire.']),
E('Air dans une pièce',r'Une pièce contient \qty{50}{m^3} d’air. On adopte 21 \% de dioxygène en volume.',[r'Estimer le volume de dioxygène.',r'Nommer le constituant majoritaire.'],[r'$V(\ce{O2})=0,21\times50=\qty{10,5}{m^3}$.',r'Le diazote représente environ 78 \% du volume.']),
E('Composition d’un alliage',r'Un alliage de 250 g contient 75,0 g de zinc et le reste de cuivre.',[r'Calculer le pourcentage massique de zinc.',r'Déterminer la masse et le pourcentage de cuivre.'],[r'$100\times75,0/250=30,0\,\%$.',r'$m_{\mathrm{Cu}}=175\unit{g}$ et $w_{\mathrm{Cu}}=70,0\,\%$. Les pourcentages somment à 100.']),
E('Une piste de chromatographie',r'La plaque présente les références R et S et le mélange M. Toutes les pistes ont été développées ensemble.',[r'Quelles espèces de référence sont compatibles avec M ?',r'M paraît-il pur dans cette analyse ?'],[r'Les taches de M correspondent aux hauteurs de R et S : les deux espèces sont compatibles avec M.',r'Non, deux taches distinctes sont détectées dans la piste M.'],'ccm-identification'),
E('Choisir un matériau',r'Un solide occupe 12,0 cm$^3$ et pèse 32,4 g. Références : aluminium 2,70 ; fer 7,87 en \unit{g.cm^{-3}}.',[r'Calculer sa masse volumique et proposer un matériau.',r'Quelle réserve faut-il conserver ?'],[r'$\rho=32,4/12,0=\qty{2,70}{g.cm^{-3}}$ : l’aluminium convient.',r'La mesure et les références ont des incertitudes ; un alliage peut donner une valeur voisine. C’est une identification à confirmer.']),
E('Du volume à la masse',r'Une bonbonne contient 40,0 L d’air de masse volumique \qty{1,20}{g.L^{-1}} dans les conditions de l’expérience.',[r'Calculer la masse d’air.',r'Peut-on déduire la masse de dioxygène en multipliant par 21 \% ?'],[r'$m=\rho V=1,20\times40,0=\qty{48,0}{g}$.',r'Non : 21 \% est une proportion volumique. Les gaz n’ont pas tous la même masse volumique.']),
E('Un bilan de mélange',r'On mélange 40 g d’une solution contenant 10 \% de sel en masse et 60 g d’eau pure. Aucune perte n’a lieu.',[r'Calculer la masse de sel conservée.',r'Déterminer le pourcentage massique final.'],[r'$m_s=0,10\times40=\qty{4}{g}$.',r'La masse totale vaut 100 g ; le pourcentage final est $100\times4/100=4\,\%$.']),
E('Une pureté à discuter',r'Un liquide bout vers 78 °C ; sa masse volumique vaut \qty{0,80}{g.mL^{-1}}. Une référence d’éthanol est voisine de ces valeurs.',[r'Peut-on affirmer qu’il s’agit d’éthanol pur ?',r'Proposer une observation complémentaire.'],[r'Ces indices sont compatibles avec l’éthanol, mais ne prouvent pas la pureté ni l’absence d’autres espèces.',r'Étudier le palier de température à pression contrôlée, compléter par une chromatographie adaptée ou un autre test pertinent.']),
E('Préparer une composition',r'Un alliage doit contenir 12,0 \% d’étain en masse pour une masse totale de 2,50 kg.',[r'Déterminer les masses d’étain et de l’autre métal.',r'Pourquoi 12 \% en volume donnerait-il un autre calcul ?'],[r'$m_{\mathrm{Sn}}=0,120\times2,50=\qty{0,300}{kg}$ et $m_{\mathrm{autre}}=\qty{2,20}{kg}$.',r'Les fractions massiques portent sur les masses ; les fractions volumiques portent sur les volumes, reliés aux masses par des masses volumiques différentes.']),
E('Un objet creux',r'Un objet fermé en métal pèse 54 g. Son volume extérieur est 30 cm$^3$ ; le métal a pour masse volumique \qty{2,7}{g.cm^{-3}}.',[r'Calculer le volume de métal.',r'En déduire le volume de la cavité, en négligeant la masse du gaz.'],[r'$V_m=m/\rho=54/2,7=\qty{20}{cm^3}$.',r'$V_{\mathrm{cavité}}=30-20=\qty{10}{cm^3}$. Le volume extérieur n’est pas le volume occupé par le métal seul.'])],
E('Contrôler une étiquette',r'Une bouteille annoncée à 15,0 \% de sucre en masse contient 250 mL de solution. La bouteille vide pèse 32,0 g et pleine 302,0 g. Une analyse indépendante trouve 40,5 g de sucre.',[r'Déterminer la masse volumique de la solution.',r'Vérifier le pourcentage annoncé.',r'Expliquer pourquoi « 15 g pour 100 mL » serait une autre annonce.'],[r'$m=270,0\unit{g}$ ; $\rho=270,0/250=\qty{1,08}{g.mL^{-1}}$.',r'$100\times40,5/270,0=15,0\,\%$ : l’annonce massique est respectée.',r'La concentration en masse vaut $40,5/0,250=\qty{162}{g.L^{-1}}$, donc 16,2 g pour 100 mL. Masse de solution et volume de solution ne se confondent pas.'],methode=r'Piste 1 : soustraire la tare. Piste 2 : identifier le dénominateur de chaque quotient. Piste 3 : comparer des grandeurs de même nature.',note=r'Un pourcentage massique et une concentration en masse répondent à deux questions différentes.'),
['Corps purs et mélanges','Tests eau, H2, O2, CO2','Masse volumique et températures','CCM','Composition massique et air'])

C('Préparer et doser une solution','colorimetrie',[
'Calculer une concentration en masse et une concentration maximale.',
'Préparer une solution par dissolution ou dilution.',
'Exploiter une gamme d’étalonnage.'],[
('Soluté, solvant et concentration',r'''Dans une solution aqueuse, l'eau joue le rôle de solvant ; une espèce dissoute est un soluté. Le volume final de solution n'est pas le volume d'eau versé avant dissolution.
\begin{definition}[Concentration en masse]$c_m=m_{\mathrm{soluté}}/V_{\mathrm{solution}}$, généralement en \unit{g.L^{-1}}. La masse volumique $\rho=m_{\mathrm{solution}}/V_{\mathrm{solution}}$ utilise la masse totale : c'est une autre grandeur.\end{definition}
À température donnée, la concentration maximale correspond à la saturation. Si on ajoute davantage de soluté que le solvant ne peut en dissoudre, une partie reste solide. La masse ajoutée n'est alors pas intégralement dissoute.'''),
('Dissoudre et diluer',r'''Pour une dissolution, calculer $m=c_mV$, peser le soluté, le dissoudre, transférer quantitativement dans la fiole, rincer les récipients et compléter au trait après dissolution et retour à température ambiante. Boucher et homogénéiser.
\schema{dissolution}
\begin{loi}[Dilution sans perte de soluté]La masse de soluté dans le prélèvement est conservée : $c_{m,\mathrm{mère}}V_{\mathrm{prélevé}}=c_{m,\mathrm{fille}}V_{\mathrm{fille}}$. Le facteur $F=V_{\mathrm{fille}}/V_{\mathrm{prélevé}}=c_{m,\mathrm{mère}}/c_{m,\mathrm{fille}}$ dépasse 1.\end{loi}
\schema{dilution}'''),
('Un dosage par étalonnage',r'''On compare une propriété mesurable d'une solution inconnue à celle de solutions de concentrations connues préparées dans les mêmes conditions. Une échelle de teintes permet une estimation visuelle ; une courbe de masse volumique peut permettre une interpolation.
\schema{etalonnage}
\begin{attention}[Le domaine de validité]Une droite expérimentale ne justifie pas une extrapolation très éloignée de la gamme. Une solution inconnue trop concentrée doit être diluée avant mesure ; il faut ensuite tenir compte du facteur de dilution.\end{attention}''')],
r'''\begin{experience}[Une dilution au laboratoire]Pour préparer 100,0 mL à partir de 10,0 mL de solution mère, rincer la pipette avec la mère, prélever avec une propipette, transférer dans une fiole jaugée de 100,0 mL, ajouter de l'eau distillée puis ajuster le bas du ménisque au trait à hauteur des yeux. Boucher et retourner plusieurs fois. Ne jamais pipeter à la bouche.\end{experience}
\begin{savoirfaire}[Choisir la verrerie]La pipette jaugée fixe un volume prélevé ; la fiole jaugée fixe un volume final. Le bécher sert à manipuler et dissoudre ; ses graduations ne remplacent pas une verrerie jaugée pour une préparation précise.\end{savoirfaire}''',[
E('Nommer les constituants',r'On dissout du glucose dans de l’eau pour obtenir une solution limpide.',[r'Nommer soluté et solvant.',r'La disparition du solide est-elle une disparition du glucose ?'],[r'Le glucose est le soluté ; l’eau est le solvant.',r'Non. Les entités de glucose sont dispersées dans la solution, elles ne cessent pas d’exister.']),
E('Concentration directe',r'Une solution contient 3,60 g de soluté dans un volume final de 200 mL.',[r'Convertir le volume en litres.',r'Calculer $c_m$.'],[r'$V=\qty{0,200}{L}$.',r'$c_m=3,60/0,200=\qty{18,0}{g.L^{-1}}$.']),
E('Préparer par dissolution',r'On souhaite 250,0 mL d’une solution à \qty{8,00}{g.L^{-1}}.',[r'Calculer la masse à peser.',r'Décrire les opérations après la pesée.'],[r'$m=8,00\times0,2500=\qty{2,00}{g}$.',r'Dissoudre, transférer et rincer quantitativement dans la fiole de 250,0 mL, compléter au trait, boucher puis homogénéiser.'],'dissolution'),
E('Une dilution par dix',r'On prélève 10,0 mL d’une mère à \qty{40,0}{g.L^{-1}}, puis on complète à 100,0 mL.',[r'Calculer le facteur de dilution.',r'Déterminer la concentration fille.'],[r'$F=100,0/10,0=10,0$.',r'$c_f=40,0/10,0=\qty{4,00}{g.L^{-1}}$.'],'dilution'),
E('Saturation',r'À la température étudiée, la concentration maximale est \qty{200}{g.L^{-1}}. On prépare 50,0 mL de solution saturée.',[r'Quelle masse maximale peut être dissoute dans ce volume final ?',r'Que se passe-t-il si 12,0 g ont été introduits pour un volume liquide final fixé à 50,0 mL ?'],[r'$m_{\max}=200\times0,0500=\qty{10,0}{g}$.',r'10,0 g se dissolvent au maximum ; 2,0 g restent solides si l’équilibre est atteint.']),
E('Choisir le prélèvement',r'On prépare 100,0 mL à \qty{3,00}{g.L^{-1}} à partir d’une mère à \qty{15,0}{g.L^{-1}}.',[r'Calculer le volume à prélever.',r'Choisir la verrerie adaptée.'],[r'$V_p=c_fV_f/c_m=3,00\times100,0/15,0=\qty{20,0}{mL}$.',r'Une pipette jaugée de 20,0 mL et une fiole jaugée de 100,0 mL, avec propipette.']),
E('Lire l’étalonnage',r'La masse volumique de la solution inconnue est \qty{1,030}{g.mL^{-1}}. Utiliser la droite fournie.',[r'Lire sa concentration en masse.',r'Cette estimation est-elle une interpolation ?'],[r'La lecture conduit à $c_m=\qty{60}{g.L^{-1}}$. La construction verte montre les projections.',r'Oui : 1,030 se situe dans l’intervalle de mesures de la gamme.'],'etalonnage'),
E('Deux masses différentes',r'100,0 mL d’une solution contiennent 5,00 g de sel. La masse totale de solution est 103,0 g.',[r'Calculer $c_m$.',r'Calculer $\rho$ et expliquer la différence.'],[r'$c_m=5,00/0,1000=\qty{50,0}{g.L^{-1}}$.',r'$\rho=103,0/100,0=\qty{1,030}{g.mL^{-1}}$. Le premier quotient utilise seulement la masse de sel, le second toute la solution.']),
E('Deux dilutions successives',r'Une solution à \qty{80,0}{g.L^{-1}} est diluée par 4 puis par 5.',[r'Déterminer la concentration finale.',r'Quel est le facteur global ?'],[r'Après la première dilution : 20,0 ; après la seconde : $\qty{4,00}{g.L^{-1}}$.',r'$F_{\mathrm{global}}=4\times5=20$. Les facteurs se multiplient.']),
E('Un trait dépassé',r'Pour préparer 100,0 mL d’une solution par dissolution, un élève dépasse le trait de jauge.',[r'La concentration obtenue est-elle trop grande ou trop petite ?',r'Retirer un peu de solution suffit-il à rétablir la concentration ?'],[r'Le volume est trop grand pour la même masse de soluté : la concentration est trop petite.',r'Non. Retirer une solution homogène retire eau et soluté dans la même proportion ; la concentration ne change pas. Il faut refaire la préparation ou la corriger par un calcul adapté.']),
E('Mélanger deux solutions',r'On mélange 100 mL à \qty{10,0}{g.L^{-1}} et 200 mL à \qty{4,00}{g.L^{-1}} du même soluté. Les volumes sont supposés additifs.',[r'Déterminer la masse totale de soluté.',r'Calculer la concentration finale.'],[r'$m=10,0\times0,100+4,00\times0,200=\qty{1,80}{g}$.',r'$c_f=1,80/0,300=\qty{6,00}{g.L^{-1}}$. Ce n’est pas la moyenne arithmétique des deux concentrations car les volumes diffèrent.']),
E('Une gamme insuffisante',r'La gamme d’étalonnage couvre 0 à \qty{100}{g.L^{-1}}. Une solution inconnue est plus concentrée que le dernier étalon. Après dilution par 5, on mesure \qty{36,0}{g.L^{-1}}.',[r'Pourquoi la dilution était-elle utile ?',r'Calculer la concentration initiale.'],[r'Elle place la solution mesurée dans le domaine couvert par les étalons, sans extrapolation hasardeuse.',r'$c_{\mathrm{initiale}}=5\times36,0=\qty{180}{g.L^{-1}}$.'])],
E('Préparer avec le stock disponible',r'On veut 250,0 mL à \qty{6,00}{g.L^{-1}} avec une mère à \qty{30,0}{g.L^{-1}}. On dispose de pipettes de 10,0 et 25,0 mL et d’une fiole de 250,0 mL.',[r'Calculer le volume mère nécessaire.',r'Proposer un protocole utilisant le matériel disponible.',r'Une prise de 25,0 mL complétée à 250,0 mL conviendrait-elle ?'],[r'$V_p=6,00\times250,0/30,0=\qty{50,0}{mL}$.',r'Effectuer deux prélèvements de 25,0 mL, les transférer dans la même fiole, puis compléter au trait et homogénéiser. Chaque prélèvement doit suivre le mode d’emploi de la pipette.',r'Non : un seul prélèvement donnerait $30,0\times25,0/250,0=\qty{3,00}{g.L^{-1}}$.'],methode=r'Piste 1 : conserver la masse de soluté. Piste 2 : combiner des prélèvements. Piste 3 : contrôler le facteur de dilution.',note=r'La dilution conserve le soluté prélevé ; le volume final est celui de la solution entière.'),
['Soluté, solvant, concentration maximale','Concentration en masse et masse volumique','Dissolution et dilution','Choix de verrerie','Étalonnage par teinte et masse volumique'])

C('Atomes, noyaux et ions','radioactivite',[
'Relier l’écriture d’un noyau à sa composition.',
'Comparer tailles et masses aux échelles atomiques.',
'Distinguer atome, molécule, cation et anion.'],[
('Une structure presque vide',r'''Un atome comporte un noyau positif entouré d'électrons négatifs. Sa taille est de l'ordre de $10^{-10}\unit{m}$, celle d'un noyau de l'ordre de $10^{-15}\unit{m}$. Le rapport des tailles vaut environ $10^5$ : le noyau occupe une très petite partie du volume atomique.
\schema{atome}
\begin{definition}[Constituants]Un proton porte $+e$, un électron $-e$, un neutron une charge nulle. $e=\qty{1,602e-19}{C}$. Les masses du proton et du neutron sont proches de \qty{1,67e-27}{kg}, celle de l'électron vaut environ \qty{9,11e-31}{kg}.\end{definition}'''),
('Identifier un noyau',r'''L'écriture $\ce{^{A}_{Z}X}$ donne $Z$ protons et $A$ nucléons, donc $A-Z$ neutrons. Le numéro atomique $Z$ définit l'élément chimique. Un atome neutre possède $Z$ électrons. Deux noyaux du même élément peuvent avoir des nombres de neutrons différents.
\begin{exemple}[Un atome de sodium]$\ce{^{23}_{11}Na}$ possède 11 protons, 12 neutrons et, à l'état neutre, 11 électrons. Sa masse est approximativement $23\times1,67\times10^{-27}=\qty{3,84e-26}{kg}$ : la masse des électrons est négligeable à cette précision.\end{exemple}'''),
('Ions et neutralité de la matière',r'''Un cation résulte d'une perte d'électrons ; un anion d'un gain d'électrons. Le noyau reste inchangé lors de cette ionisation. $\ce{Na+}$ a 10 électrons, $\ce{Cl-}$ en a 18. Une molécule est un assemblage électriquement neutre d'atomes liés.
\begin{propriete}[Composé ionique]La formule indique les proportions d'ions nécessaires à la neutralité. $\ce{CaCl2}$ associe un ion $\ce{Ca^{2+}}$ à deux ions $\ce{Cl-}$ ; ce solide n'est pas un ensemble de molécules isolées de chlorure de calcium.\end{propriete}''')],
r'''\begin{experience}[Construire un modèle]Avec des jetons, représenter les protons, neutrons et électrons d'un atome, puis de son ion. Dresser deux bilans : nombre de nucléons inchangé, nombre d'électrons modifié. Le modèle représente les nombres et les charges, pas les dimensions réelles ni des orbites planétaires.\end{experience}''',[
E('Lire une écriture nucléaire',r'On considère $\ce{^{27}_{13}Al}$.',[r'Donner les nombres de protons et de neutrons.',r'Donner le nombre d’électrons de l’atome neutre.'],[r'$Z=13$ protons et $A-Z=27-13=14$ neutrons.',r'13 électrons compensent les 13 charges positives.']),
E('Écrire un noyau',r'Un noyau d’oxygène contient 8 protons et 10 neutrons.',[r'Déterminer $Z$ et $A$.',r'Écrire son symbole nucléaire.'],[r'$Z=8$ et $A=8+10=18$.',r'$\ce{^{18}_{8}O}$.']),
E('Qualifier une entité',r'On donne $\ce{Ne}$, $\ce{CO2}$, $\ce{Mg^{2+}}$ et $\ce{F-}$.',[r'Associer les mots atome, molécule, cation et anion.',r'Quelle entité porte deux charges élémentaires positives ?'],[r'Ne : atome ; \ce{CO2} : molécule ; \ce{Mg^{2+}} : cation ; \ce{F-} : anion.',r'\ce{Mg^{2+}}, de charge $+2e$.']),
E('Un anion chlorure',r'Le chlore possède $Z=17$.',[r'Combien d’électrons possède \ce{Cl-} ?',r'La formation de cet ion change-t-elle le noyau ?'],[r'18 électrons : un électron a été gagné par rapport à l’atome neutre.',r'Non. L’élément reste le chlore avec 17 protons.']),
E('Changer d’échelle',r'Un atome mesure environ $10^{-10}\unit{m}$ et son noyau $10^{-15}\unit{m}$.',[r'Calculer le rapport des tailles.',r'Si l’atome avait un diamètre de 100 m, quel serait celui du noyau ?'],[r'$10^{-10}/10^{-15}=10^5$.',r'$100/10^5=\qty{0,001}{m}=\qty{1}{mm}$. Le dessin du livre n’est donc pas à l’échelle.'],'atome'),
E('Une masse atomique',r'On assimile les masses des nucléons à \qty{1,67e-27}{kg}. Un atome de carbone possède 12 nucléons.',[r'Estimer sa masse.',r'Pourquoi la masse des six électrons est-elle négligeable ici ?'],[r'$m\simeq12\times1,67\times10^{-27}=\qty{2,00e-26}{kg}$.',r'Leur masse totale vaut environ $5,47\times10^{-30}\unit{kg}$, très petite devant celle du noyau.']),
E('Charge du noyau',r'Un noyau de magnésium possède 12 protons ; $e=\qty{1,60e-19}{C}$.',[r'Calculer sa charge.',r'Quelle est la charge totale des électrons de l’atome neutre ?'],[r'$q_n=12e=\qty{1,92e-18}{C}$.',r'$q_e=-12e=\qty{-1,92e-18}{C}$. Les charges se compensent.']),
E('Neutraliser les charges',r'On associe des ions $\ce{Al^{3+}}$ et $\ce{O^{2-}}$.',[r'Trouver les plus petits nombres d’ions assurant la neutralité.',r'En déduire la formule du composé.'],[r'Deux ions aluminium apportent $+6e$ et trois ions oxyde $-6e$.',r'$\ce{Al2O3}$. Les indices traduisent le rapport 2 pour 3.']),
E('Un ion à identifier',r'Une entité possède 11 protons, 12 neutrons et 10 électrons.',[r'Déterminer sa charge en multiples de $e$.',r'Donner son symbole et le nombre de masse du noyau.'],[r'$q=(11-10)e=+e$.',r'C’est $\ce{Na+}$ ; son noyau a $A=23$.']),
E('Une erreur de vocabulaire',r'Un texte affirme : « Le cation calcium se forme quand le noyau gagne deux protons ».',[r'Corriger l’explication.',r'Que provoquerait réellement un changement de nombre de protons ?'],[r'L’ion $\ce{Ca^{2+}}$ se forme par perte de deux électrons ; le noyau reste inchangé.',r'Le numéro atomique changerait : il s’agirait d’un autre élément chimique.']),
E('Masse et charge',r'Un ion possède un noyau $\ce{^{24}_{12}Mg}$ et 10 électrons.',[r'Calculer sa charge avec $e=\qty{1,60e-19}{C}$.',r'Comparer sa masse à celle de l’atome neutre.'],[r'$q=(12-10)e=\qty{3,20e-19}{C}$.',r'Il manque deux électrons, soit environ $1,82\times10^{-30}\unit{kg}$, négligeable devant $24\times1,67\times10^{-27}\unit{kg}$. Les masses sont presque égales.']),
E('Un solide électriquement neutre',r'Un échantillon contient $3,0\times10^{20}$ ions $\ce{Ca^{2+}}$ et uniquement des ions chlorure pour compenser.',[r'Combien d’ions chlorure contient-il ?',r'Calculer la charge totale du solide.'],[r'Il faut deux ions chlorure par ion calcium : $6,0\times10^{20}$ ions $\ce{Cl-}$.',r'$q=3,0\times10^{20}\times2e-6,0\times10^{20}e=0$.'])],
E('Reconstituer une entité',r'Un noyau possède 16 nucléons dont 8 neutrons. L’entité qui le contient porte la charge $-2e$.',[r'Identifier l’élément et écrire le noyau.',r'Déterminer le nombre d’électrons.',r'Associer cet ion à $\ce{Na+}$ pour écrire un composé neutre.'],[r'Il possède $16-8=8$ protons : c’est l’oxygène, $\ce{^{16}_{8}O}$.',r'La charge négative traduit deux électrons supplémentaires : 10 électrons.',r'Deux ions sodium par ion oxyde : $\ce{Na2O}$.'],methode=r'Piste 1 : $A=Z+N_{\mathrm{neutrons}}$. Piste 2 : $q=(Z-N_e)e$. Piste 3 : sommer les charges.',note=r'Le noyau identifie l’élément ; le cortège électronique détermine la charge de l’ion.'),
['Atome, molécule, anion, cation','Composition du noyau et écriture A/Z','Masses et charges','Rapports d’échelles','Électroneutralité des composés ioniques'])

C('Électrons et stabilité','lewis',[
'Lire une configuration électronique pour Z inférieur ou égal à 18.',
'Relier familles, électrons de valence et ions usuels.',
'Interpréter un schéma de Lewis fourni.'],[
('Remplir les sous-couches',r'''Pour les atomes étudiés jusqu'à $Z=18$, les sous-couches se remplissent dans l'ordre 1s, 2s, 2p, 3s, 3p ; leurs capacités maximales sont respectivement 2, 2, 6, 2 et 6 électrons. La somme des exposants vaut le nombre d'électrons.
\begin{exemple}[Le soufre]Pour $Z=16$, la configuration est $1s^2\,2s^2\,2p^6\,3s^2\,3p^4$. La couche externe est celle de nombre 3 : elle contient 6 électrons de valence.\end{exemple}
La plus grande valeur du nombre de couche occupée donne la période. Pour les éléments des blocs s et p, les électrons de valence permettent de retrouver la colonne, avec le cas particulier de l'hélium, gaz noble à deux électrons.
\schema{tableau-periodique}'''),
('Des entités plus stables',r'''Les gaz nobles ont une couche de valence saturée : deux électrons pour l'hélium, huit pour le néon et l'argon. Cette configuration aide à prévoir des ions monoatomiques usuels : le sodium perd un électron ; le magnésium en perd deux ; le fluor et le chlore en gagnent un.
\begin{definition}[Noms à connaître]$\ce{H+}$ : ion hydrogène ; $\ce{Na+}$ : sodium ; $\ce{K+}$ : potassium ; $\ce{Ca^{2+}}$ : calcium ; $\ce{Mg^{2+}}$ : magnésium ; $\ce{Cl-}$ : chlorure ; $\ce{F-}$ : fluorure.\end{definition}
Les membres d'une famille, dans une même colonne, ont des propriétés chimiques communes liées à leurs électrons de valence.'''),
('Lire les schémas de Lewis',r'''Un trait entre deux atomes représente un doublet liant, donc deux électrons partagés. Un doublet non liant appartient à un seul atome. Pour compter les électrons autour d'un atome, chaque doublet voisin compte pour deux, même s'il est partagé.
\schema{lewis}
\begin{exemple}Dans le schéma fourni de l'eau, l'oxygène possède deux doublets liants et deux non liants : huit électrons l'entourent. Chaque hydrogène est entouré de deux électrons.\end{exemple}
Rompre une liaison demande de l'énergie. Une liaison plus difficile à rompre a une énergie de liaison plus élevée ; former des liaisons libère de l'énergie. En Seconde, on interprète les schémas fournis : aucune méthode générale de construction complexe n'est nécessaire.''')],
r'''\begin{experience}[Confronter des modèles]Utiliser le tableau périodique et les schémas fournis pour compter les électrons de valence puis les doublets autour de chaque atome. Présenter un tableau de vérification pour \ce{H2}, \ce{H2O}, \ce{NH3} et \ce{CO2}. Les modèles de boules montrent l'enchaînement des atomes, mais pas tous les doublets.\end{experience}''',[
E('Additionner les exposants',r'La configuration d’un atome neutre est $1s^2\,2s^2\,2p^5$.',[r'Combien a-t-il d’électrons ?',r'Identifier l’élément avec le tableau fourni.'],[r'$2+2+5=9$ électrons, donc $Z=9$.',r'C’est le fluor F.'],'tableau-periodique'),
E('Électrons de valence',r'Le magnésium a pour configuration $1s^2\,2s^2\,2p^6\,3s^2$.',[r'Donner la période et le nombre d’électrons de valence.',r'Prévoir l’ion monoatomique usuel.'],[r'Période 3, deux électrons de valence dans la couche externe.',r'La perte de deux électrons conduit à $\ce{Mg^{2+}}$, de configuration externe identique à celle du néon.']),
E('Nom et formule',r'On donne les noms sodium, chlorure, calcium et fluorure pour des ions usuels.',[r'Écrire les quatre formules ioniques.',r'Classer les ions en cations et anions.'],[r'$\ce{Na+}$, $\ce{Cl-}$, $\ce{Ca^{2+}}$, $\ce{F-}$.',r'Sodium et calcium : cations ; chlorure et fluorure : anions.']),
E('Interpréter l’eau',r'Utiliser le schéma de Lewis fourni pour \ce{H2O}.',[r'Compter les doublets liants et non liants de l’oxygène.',r'Vérifier le duet de chaque hydrogène.'],[r'L’oxygène possède 2 doublets liants et 2 non liants, soit 8 électrons autour de lui.',r'Chaque H partage un doublet liant, donc est entouré de 2 électrons.'],'lewis'),
E('Écrire une configuration',r'Le silicium a $Z=14$.',[r'Écrire sa configuration fondamentale.',r'Donner sa période et ses électrons de valence.'],[r'$1s^2\,2s^2\,2p^6\,3s^2\,3p^2$ ; les exposants somment à 14.',r'Période 3 ; 4 électrons de valence.']),
E('Deux membres d’une famille',r'L’oxygène est $1s^2\,2s^2\,2p^4$ ; le soufre est $1s^2\,2s^2\,2p^6\,3s^2\,3p^4$.',[r'Quel point commun de valence présentent-ils ?',r'Pourquoi sont-ils dans une même colonne ?'],[r'Leur couche externe contient six électrons, sous la forme $s^2p^4$.',r'Cette structure de valence commune explique leur appartenance à une même famille et certaines propriétés analogues.']),
E('Un octet dans le dioxyde de carbone',r'Le schéma de \ce{CO2} est fourni.',[r'Combien de doublets liants entourent le carbone ?',r'Vérifier l’octet du carbone et d’un oxygène.'],[r'Deux liaisons doubles correspondent à quatre doublets liants autour du carbone.',r'Carbone : $4\times2=8$ électrons. Chaque oxygène a 2 doublets liants et 2 non liants, donc 8 électrons.'],'lewis'),
E('Comparer des liaisons',r'Pour deux liaisons isolées, on fournit des énergies de rupture de $3,0\times10^{-19}$ J et $5,0\times10^{-19}$ J.',[r'Laquelle demande le plus d’énergie pour être rompue ?',r'Rompre une liaison libère-t-il de l’énergie ?'],[r'La seconde : son énergie de rupture est plus grande.',r'Non, rompre une liaison nécessite un apport d’énergie. C’est la formation d’une liaison qui en libère.']),
E('Un gaz noble particulier',r'L’hélium possède $1s^2$ ; le néon $1s^2\,2s^2\,2p^6$.',[r'Pourquoi sont-ils tous deux chimiquement stables ?',r'Faut-il huit électrons autour de l’hélium ?'],[r'Leur couche externe est complète dans le modèle étudié.',r'Non : la couche 1 ne peut contenir que deux électrons. Le duet suffit pour l’hélium.']),
E('Corriger un remplissage',r'Une proposition pour le sodium est $1s^2\,2s^2\,2p^7$.',[r'Identifier l’erreur.',r'Donner la configuration correcte et l’ion usuel.'],[r'La sous-couche 2p ne peut contenir que six électrons.',r'$1s^2\,2s^2\,2p^6\,3s^1$ ; l’ion est $\ce{Na+}$.']),
E('La molécule d’ammoniac',r'Le schéma fourni représente \ce{NH3}.',[r'Compter les électrons autour de l’azote.',r'Compter le nombre total de doublets figurés dans la molécule.'],[r'3 doublets liants et 1 non liant : 8 électrons entourent l’azote.',r'Il y a 4 doublets au total, soit 8 électrons de valence représentés. Les doublets partagés ne se comptent qu’une fois dans le total moléculaire.'],'lewis'),
E('Atome ou ion ?',r'Deux entités ont dix électrons. Leurs noyaux possèdent respectivement 10 et 12 protons.',[r'Identifier l’atome neutre et le cation.',r'Que partagent leurs configurations électroniques ?'],[r'10 protons : atome de néon ; 12 protons et 10 électrons : ion $\ce{Mg^{2+}}$.',r'Les deux configurations sont $1s^2\,2s^2\,2p^6$. Même cortège ne signifie pas même élément.'])],
E('Retrouver un élément',r'Un atome appartient à la période 3 et possède sept électrons de valence. On se limite aux 18 premiers éléments.',[r'Écrire sa configuration et identifier l’élément.',r'Prévoir la charge de son ion usuel.',r'Expliquer pourquoi l’ion et le gaz noble voisin restent deux espèces différentes.'],[r'$1s^2\,2s^2\,2p^6\,3s^2\,3p^5$ : 17 électrons, c’est le chlore.',r'Il gagne un électron : $\ce{Cl-}$, avec la configuration de l’argon.',r'Le chlorure possède 17 protons et une charge négative ; l’argon en possède 18 et est neutre. Leurs noyaux diffèrent.'],methode=r'Piste 1 : remplir les deux premières couches. Piste 2 : placer sept électrons dans la troisième. Piste 3 : comparer les noyaux.',note=r'Une configuration de valence stable explique la formation de l’ion ; elle ne change pas l’identité du noyau.'),
['Configurations 1s, 2s, 2p, 3s, 3p','Position et familles du tableau périodique','Gaz nobles et ions usuels','Lewis fourni, doublets et stabilité','Énergie de liaison qualitative'])

C('Compter les entités','mole',[
'Calculer la masse d’une entité à partir de sa formule.',
'Passer d’une masse à un nombre d’entités.',
'Utiliser la définition de la mole.'],[
('De la formule à la masse',r'''Une formule brute indique les atomes présents dans une entité et leur nombre. Dans \ce{CO2}, il y a un atome de carbone et deux d'oxygène. Pour calculer la masse d'une molécule à la précision du cours, additionner les masses des atomes qui la constituent.
\begin{exemple}[Une molécule d'eau]Avec $m_H=\qty{1,67e-27}{kg}$ et $m_O=\qty{2,66e-26}{kg}$, $m_{\ce{H2O}}=2m_H+m_O=\qty{2,994e-26}{kg}$. Les indices multiplient les masses correspondantes.\end{exemple}'''),
('Une masse contient combien d’entités ?',r'''\begin{loi}[Entités identiques]Pour un échantillon pur de masse $m$, le nombre d'entités vaut $N=m/m_{\mathrm{entité}}$. Les deux masses doivent être exprimées dans la même unité. $N$ est un nombre sans unité.\end{loi}
Les valeurs obtenues sont souvent immenses ; l'écriture scientifique permet de les manipuler. Dans un mélange, il faut d'abord isoler la masse de l'espèce étudiée : on ne divise pas la masse totale du mélange par la masse d'une seule sorte d'entité.
\schema{mole}'''),
('La mole, un paquet de comptage',r'''\begin{definition}[Quantité de matière]Une mole contient exactement $\num{6,02214076e23}$ entités. La constante d'Avogadro vaut $N_A=\qty{6,02214076e23}{mol^{-1}}$ ; $n=N/N_A$ s'exprime en moles. En entraînement on utilise souvent $N_A\simeq\qty{6,02e23}{mol^{-1}}$.\end{definition}
Une mole d'eau et une mole de dioxyde de carbone contiennent le même nombre de molécules, mais leurs masses diffèrent. Le parcours demandé ici est : masse d'une entité, nombre d'entités, quantité de matière. La masse molaire sera formalisée en Première.
\begin{exemple}Un échantillon de \qty{2,994}{g} d'eau contient $N=2,994\times10^{-3}/(2,994\times10^{-26})=10^{23}$ molécules ; $n=10^{23}/(6,02\times10^{23})\simeq\qty{0,166}{mol}$.\end{exemple}''')],
r'''\begin{experience}[Peser pour compter]Comparer un lot de rondelles identiques et un échantillon de matière : la masse moyenne d'une rondelle permet de compter indirectement le lot. Identifier l'hypothèse d'identité des objets. Transposer ensuite la démarche à des atomes ou molécules en utilisant les masses fournies, sans prétendre peser une molécule sur une balance scolaire.\end{experience}''',[
E('Lire les indices',r'Une molécule de glucose a pour formule \ce{C6H12O6}.',[r'Combien d’atomes contient-elle au total ?',r'Combien d’atomes d’hydrogène contiennent 100 molécules ?'],[r'$6+12+6=24$ atomes.',r'$100\times12=1200$ atomes d’hydrogène.']),
E('Masse d’une molécule',r'$m_C=\qty{1,99e-26}{kg}$ et $m_O=\qty{2,66e-26}{kg}$.',[r'Calculer la masse d’une molécule de \ce{CO2}.',r'Exprimer cette masse en grammes.'],[r'$m=1,99\times10^{-26}+2\times2,66\times10^{-26}=\qty{7,31e-26}{kg}$.',r'$\qty{7,31e-23}{g}$ car un kilogramme vaut mille grammes.']),
E('Un nombre d’atomes',r'Un échantillon pur de cuivre pèse 1,06 g. Un atome de cuivre pèse \qty{1,06e-25}{kg}.',[r'Convertir la masse de l’échantillon en kilogrammes.',r'Calculer le nombre d’atomes.'],[r'$m=\qty{1,06e-3}{kg}$.',r'$N=1,06\times10^{-3}/(1,06\times10^{-25})=\num{1,00e22}$.']),
E('Passer à la mole',r'Un échantillon contient $3,01\times10^{23}$ molécules. On adopte $N_A=\qty{6,02e23}{mol^{-1}}$.',[r'Calculer la quantité de matière.',r'Combien d’entités y aurait-il dans 2,00 mol ?'],[r'$n=3,01\times10^{23}/(6,02\times10^{23})=\qty{0,500}{mol}$.',r'$N=nN_A=\num{1,20e24}$ après arrondi à trois chiffres significatifs.'],'mole'),
E('Le dioxygène',r'Un atome d’oxygène pèse \qty{2,66e-26}{kg}. Un échantillon de \ce{O2} pèse 0,532 g.',[r'Calculer la masse d’une molécule de \ce{O2}.',r'Déterminer $N$ puis $n$ avec $N_A=\qty{6,02e23}{mol^{-1}}$.'],[r'$m_e=2\times2,66\times10^{-26}=\qty{5,32e-26}{kg}$.',r'$N=5,32\times10^{-4}/(5,32\times10^{-26})=10^{22}$ ; $n=\qty{0,0166}{mol}$.']),
E('Atomes et molécules',r'Une quantité de 0,200 mol de \ce{CO2} est considérée.',[r'Donner les quantités d’atomes de carbone et d’oxygène correspondantes.',r'Peut-on dire qu’il y a 0,200 mol d’atomes au total ?'],[r'Il y a 0,200 mol d’atomes de C et 0,400 mol d’atomes de O.',r'Non : le total est 0,600 mol d’atomes, chaque molécule contenant trois atomes.']),
E('Revenir à la masse',r'On souhaite $2,00\times10^{22}$ molécules de masse individuelle \qty{3,00e-26}{kg}.',[r'Calculer la masse de l’échantillon.',r'Exprimer cette masse dans une unité pratique pour une balance.'],[r'$m=Nm_e=2,00\times10^{22}\times3,00\times10^{-26}=\qty{6,00e-4}{kg}$.',r'$m=\qty{0,600}{g}$.']),
E('Une espèce dans un mélange',r'Un échantillon de 5,00 g contient 20,0 \% en masse d’une espèce dont chaque entité pèse \qty{5,00e-26}{kg}.',[r'Calculer la masse de cette espèce.',r'Calculer son nombre d’entités.'],[r'$m=0,200\times5,00=\qty{1,00}{g}$.',r'$N=1,00\times10^{-3}/(5,00\times10^{-26})=\num{2,00e22}$.']),
E('Même nombre, masses différentes',r'Une molécule A pèse $3,00\times10^{-26}$ kg et une molécule B $6,00\times10^{-26}$ kg.',[r'Comparer les masses de deux échantillons contenant chacun $10^{23}$ molécules.',r'Comparer leurs quantités de matière.'],[r'$m_A=\qty{3,00}{g}$ et $m_B=\qty{6,00}{g}$ : B est deux fois plus massif.',r'Les quantités de matière sont égales puisqu’elles correspondent au même nombre d’entités.']),
E('Un solide ionique',r'Un échantillon contient $6,02\times10^{22}$ motifs \ce{CaCl2}. Chaque motif correspond à un ion calcium et deux ions chlorure.',[r'Calculer les nombres d’ions de chaque sorte.',r'Donner leurs quantités de matière.'],[r'$N_{\mathrm{Ca}}=6,02\times10^{22}$ et $N_{\mathrm{Cl}}=1,204\times10^{23}$.',r'$n_{\mathrm{Ca}}=\qty{0,100}{mol}$ ; $n_{\mathrm{Cl}}=\qty{0,200}{mol}$. Le mot motif évite de parler à tort de molécules dans le solide.']),
E('Une très petite quantité',r'Une goutte de masse 0,0300 g ne contient que des molécules de masse \qty{3,00e-26}{kg}.',[r'Calculer le nombre de molécules.',r'Comparer ce nombre à un milliard.'],[r'$N=3,00\times10^{-5}/(3,00\times10^{-26})=10^{21}$.',r'$10^{21}/10^9=10^{12}$ : le nombre de molécules vaut mille milliards de fois un milliard.']),
E('Détecter un facteur mille',r'Un élève divise 1,80 g par $3,00\times10^{-26}$ kg et annonce $6,00\times10^{25}$ molécules.',[r'Identifier son erreur.',r'Corriger $N$ puis calculer $n$.'],[r'Il a utilisé deux unités différentes pour les masses.',r'$N=1,80\times10^{-3}/(3,00\times10^{-26})=\num{6,00e22}$ ; $n=6,00/6,02\times10^{-1}=\qty{0,0997}{mol}$.'])],
E('Une solution vue de deux échelles',r'Une solution de volume 250 mL a une concentration de glucose de \qty{12,0}{g.L^{-1}}. On donne $m_C=1,99\times10^{-26}$ kg, $m_H=1,67\times10^{-27}$ kg, $m_O=2,66\times10^{-26}$ kg et $N_A=6,02\times10^{23}\unit{mol^{-1}}$.',[r'Calculer la masse d’une molécule \ce{C6H12O6}.',r'Déterminer le nombre de molécules de glucose dans la solution.',r'En déduire sa quantité de matière.'],[r'$m_e=6m_C+12m_H+6m_O=\qty{2,9904e-25}{kg}$.',r'$m=12,0\times0,250=\qty{3,00}{g}$ ; $N=3,00\times10^{-3}/m_e\simeq\num{1,00e22}$.',r'$n=N/N_A\simeq\qty{0,0167}{mol}$. On a compté uniquement le glucose, sans inclure l’eau.'],methode=r'Piste 1 : utiliser tous les indices de la formule. Piste 2 : concentration fois volume. Piste 3 : passer aux kilogrammes avant de compter.',note=r'Les quotients $m/m_e$ et $N/N_A$ relient la masse macroscopique au comptage microscopique.'),
['Masse d’une entité à partir de sa formule','Nombre d’entités N = m / m_entité','Définition exacte de la mole','Quantité n = N / N_A'])

C('Changements d’état et énergie','thermo',[
'Modéliser un changement d’état à deux échelles.',
'Distinguer dissolution, fusion et transformation chimique.',
'Relier masse transformée et énergie échangée.'],[
('Les six changements d’état',r'''Fusion : solide vers liquide ; solidification : liquide vers solide ; vaporisation : liquide vers gaz ; liquéfaction : gaz vers liquide ; sublimation : solide vers gaz ; condensation solide : gaz vers solide. L'espèce reste la même. L'écriture $\ce{H2O(s) -> H2O(l)}$ décrit une fusion.
\schema{etats}
À l'échelle microscopique, les entités se réorganisent et leur mobilité change. Elles ne deviennent pas une autre espèce. La dissolution du sucre dans l'eau n'est pas une fusion : elle met en jeu un solvant.'''),
('Température et état physique',r'''À pression fixée, un corps pur peut changer d'état à température constante : l'énergie reçue sert alors à modifier l'organisation de la matière. Un palier sur une courbe est un indice, à interpréter avec les conditions expérimentales. L'évaporation en surface peut avoir lieu sans ébullition de tout le liquide.
\schema{palier}
\begin{attention}La masse totale se conserve dans un système fermé, mais le volume peut varier. L'eau solide est moins dense que l'eau liquide : une bouteille pleine peut être endommagée si elle gèle.\end{attention}'''),
('Le transfert thermique',r'''Une transformation endothermique reçoit de l'énergie thermique du milieu ; une transformation exothermique en cède. La fusion et la vaporisation sont endothermiques ; la solidification et la liquéfaction sont exothermiques.
\begin{loi}[Énergie de changement d'état]Pour une masse $m$ transformée à la température du changement d'état, la valeur de l'énergie échangée est $E=mL$, où $L$ est l'énergie massique correspondante en \unit{J.kg^{-1}}. Préciser séparément le sens du transfert.\end{loi}
\begin{exemple}Faire fondre \qty{0,100}{kg} de glace à 0 °C, avec $L_f=\qty{3,34e5}{J.kg^{-1}}$, demande \qty{3,34e4}{J}. Ce calcul ne couvre pas le chauffage préalable d'une glace à température négative.\end{exemple}''')],
r'''\begin{experience}[Étudier un palier]Relever la température d'un corps pur pendant un chauffage doux, à intervalles réguliers ; noter les états présents. Tracer température en fonction du temps avec unités. Discuter les échanges avec l'environnement et la position de la sonde. Pour comparer l'énergie échangée à deux masses, garder le même changement d'état et les mêmes conditions.\end{experience}''',[
E('Nommer les changements',r'Des gouttes apparaissent sur une vitre froide ; un glaçon disparaît dans un verre.',[r'Nommer les deux changements d’état.',r'L’espèce eau a-t-elle changé ?'],[r'Liquéfaction de la vapeur d’eau sur la vitre ; fusion du glaçon.',r'Non, les entités restent des molécules de \ce{H2O}.']),
E('Écrire symboliquement',r'On transforme de l’eau liquide en vapeur.',[r'Écrire l’équation du changement d’état.',r'Qualifier le transfert thermique pour l’eau.'],[r'$\ce{H2O(l) -> H2O(g)}$.',r'La vaporisation est endothermique : l’eau reçoit de l’énergie.']),
E('Calculer une énergie de fusion',r'On fait fondre 50,0 g de glace à 0 °C. $L_f=\qty{3,34e5}{J.kg^{-1}}$.',[r'Convertir la masse en kilogrammes.',r'Calculer l’énergie reçue.'],[r'$m=\qty{0,0500}{kg}$.',r'$E=mL_f=0,0500\times3,34\times10^5=\qty{1,67e4}{J}$.']),
E('Dissoudre ou fondre ?',r'Un sucre solide disparaît dans de l’eau à 20 °C ; un morceau de cire devient liquide quand on le chauffe.',[r'Identifier les deux transformations.',r'Quelle opération implique un solvant ?'],[r'Le sucre se dissout ; la cire fond.',r'La dissolution fait intervenir l’eau comme solvant.']),
E('Lire une courbe thermique',r'Une courbe idéalisée décrit le chauffage d’un corps pur à pression constante.',[r'Identifier le changement pendant le palier.',r'Expliquer pourquoi la température n’augmente pas pendant cet intervalle.'],[r'Le palier à 0 °C correspond à la fusion dans l’exemple de l’eau.',r'L’énergie reçue permet le changement d’organisation du solide en liquide, au lieu d’élever la température du corps pur.'],'palier'),
E('Une masse à solidifier',r'La solidification libère 66,8 kJ. $L_f=\qty{334}{kJ.kg^{-1}}$.',[r'Déterminer la masse d’eau solidifiée.',r'Quel milieu reçoit l’énergie ?'],[r'$m=E/L_f=66,8/334=\qty{0,200}{kg}$.',r'Le milieu extérieur reçoit l’énergie cédée par l’eau ; la solidification est exothermique.']),
E('Deux masses de glace',r'Deux blocs de même glace à 0 °C ont des masses de 40 g et 100 g.',[r'Comparer les énergies nécessaires à leur fusion complète.',r'Faut-il utiliser la même valeur de $L_f$ ?'],[r'$E_2/E_1=m_2/m_1=100/40=2,5$.',r'Oui : c’est le même changement d’état de la même espèce dans les mêmes conditions.']),
E('Une évaporation qui refroidit',r'De l’eau s’évapore sur la peau.',[r'Dans quel sens l’énergie est-elle transférée ?',r'Pourquoi la peau peut-elle refroidir ?'],[r'L’eau reçoit de l’énergie, notamment de la peau, pour se vaporiser.',r'La peau cède de l’énergie thermique ; sa température peut diminuer si cet apport n’est pas compensé.']),
E('Une puissance utile fournie',r'Un dispositif fournit effectivement \qty{100}{J} chaque seconde à de la glace à 0 °C. La masse est 0,200 kg et $L_f=\qty{3,34e5}{J.kg^{-1}}$.',[r'Calculer l’énergie de fusion.',r'Estimer la durée de fusion, sans autre perte.'],[r'$E=0,200\times3,34\times10^5=\qty{6,68e4}{J}$.',r'$t=66800/100=\qty{668}{s}$, soit environ 11,1 min. Le débit d’énergie utile est fourni dans l’énoncé.']),
E('Masse conservée, volume changé',r'100 g d’eau liquide deviennent de la glace. $\rho_l=\qty{1,00}{g.cm^{-3}}$, $\rho_s=\qty{0,92}{g.cm^{-3}}$.',[r'Calculer les volumes avant et après.',r'Pourquoi un récipient rigide plein pose-t-il problème ?'],[r'$V_l=\qty{100}{cm^3}$ ; $V_s=100/0,92\simeq\qty{109}{cm^3}$.',r'Le volume augmente d’environ 9 cm$^3$ ; sans espace libre, la solidification peut exercer des contraintes importantes.']),
E('Une étape oubliée',r'On veut transformer de la glace à -10 °C en eau à 20 °C.',[r'Pourquoi $E=mL_f$ seul ne suffit-il pas ?',r'Lister les trois étapes physiques.'],[r'Cette relation ne calcule que l’énergie de fusion à la température de fusion.',r'Chauffer la glace jusqu’à 0 °C ; la faire fondre ; chauffer l’eau liquide jusqu’à 20 °C.']),
E('Comparer deux matériaux',r'Pour la même masse, A a une énergie de fusion massique de 180 kJ/kg et B de 300 kJ/kg.',[r'Lequel stocke davantage d’énergie par fusion ?',r'Quelle autre condition faut-il vérifier pour un usage à 20 °C ?'],[r'B : son énergie échangée par kilogramme transformé est supérieure.',r'Il faut connaître sa température de fusion et vérifier qu’elle convient à la plage de fonctionnement.'])],
E('Une réserve de froid',r'Un accumulateur contient 0,300 kg de glace à 0 °C. Le milieu lui transmet en moyenne 25 J chaque seconde. $L_f=\qty{3,34e5}{J.kg^{-1}}$.',[r'Déterminer l’énergie absorbable avant fusion complète.',r'Estimer la durée de maintien du mélange glace-eau à 0 °C.',r'Expliquer ce que le modèle ne prévoit pas après cette durée.'],[r'$E=0,300\times3,34\times10^5=\qty{1,002e5}{J}$.',r'$t=100200/25=\qty{4008}{s}$, soit environ 67 min, sous l’hypothèse d’un apport constant.',r'Après disparition de la glace, l’eau liquide se réchauffe. Le calcul de fusion seul ne détermine pas cette élévation de température.'],methode=r'Piste 1 : toute la masse change d’état. Piste 2 : diviser l’énergie par l’apport par seconde. Piste 3 : examiner la fin du palier.',note=r'Un changement d’état peut échanger de l’énergie sans variation de température du corps pur.'),
['Six changements d’état et écriture','Modèle microscopique','Fusion et dissolution','Endothermique et exothermique','Énergie E = mL'])

C('Réactions chimiques et bilans','avancement',[
'Identifier réactifs, produits et espèces spectatrices.',
'Ajuster une équation en conservant atomes et charge.',
'Déterminer le réactif limitant et interpréter un effet thermique.'],[
('Observer puis modéliser',r'''Une transformation chimique modifie les espèces présentes : certains réactifs sont consommés et des produits apparaissent. Un dégagement gazeux ou une couleur qui change est un indice à compléter par l'identification des espèces. L'équation ne décrit pas toutes les étapes microscopiques ; elle fournit un bilan.
\begin{savoirfaire}[Ajuster]Écrire les formules correctes, puis changer uniquement les coefficients devant les formules. Conserver le nombre d'atomes de chaque élément et la charge totale. Pour une combustion complète du méthane : $\ce{CH4 + 2 O2 -> CO2 + 2 H2O}$.\end{savoirfaire}
Les espèces spectatrices sont présentes mais inchangées ; on peut les omettre de l'équation ionique simplifiée.'''),
('Proportions et réactif limitant',r'''Les coefficients donnent des proportions de nombres d'entités ou de quantités de matière, jamais directement de masses. Dans $\ce{2 H2 + O2 -> 2 H2O}$, deux moles de dihydrogène réagissent avec une mole de dioxygène.
\schema{reaction}
\begin{definition}[Transformation totale]Le réactif limitant est entièrement consommé à l'issue de la transformation totale modélisée. Pour le trouver, comparer les quantités disponibles divisées par leurs coefficients ; le plus petit rapport fixe la limite. Si les rapports sont égaux, les proportions sont stœchiométriques.\end{definition}
La présence d'un réactif dans l'état final peut montrer qu'il était en excès, si l'on sait que la transformation a été totale.'''),
('Réactions usuelles et effet thermique',r'''Exemples à savoir exploiter : $\ce{C + O2 -> CO2}$ ; $\ce{Zn + 2 H+ -> Zn^{2+} + H2}$ ; $\ce{CaCO3 + 2 H+ -> Ca^{2+} + CO2 + H2O}$ ; $\ce{H+ + HO- -> H2O}$. Les ions chlorure d'une solution d'acide chlorhydrique peuvent rester spectateurs.
\begin{propriete}[Échanges d'énergie]Une transformation exothermique cède de l'énergie au milieu ; une transformation endothermique en reçoit. Une hausse de température dans un montage suffisamment isolé est un indice du caractère exothermique. La température dépend aussi des pertes et des quantités utilisées.\end{propriete}''')],
r'''\begin{experience}[Repérer le réactif limitant]Au laboratoire encadré, faire réagir de petites quantités de carbonate de calcium avec une solution acide ; mettre en évidence le gaz formé et rechercher du solide restant. Comparer des essais en faisant varier une seule quantité initiale. Ne pas fermer hermétiquement un montage qui dégage un gaz.\end{experience}
\begin{experience}[Suivre la température]Relever la température avant mélange puis son évolution, avec le même récipient et le même volume total pour comparer plusieurs essais. Doubler la masse du réactif limitant n'implique une proportionnalité de l'effet observé que si les autres conditions restent adaptées.\end{experience}''',[
E('Lire une équation',r'$\ce{C + O2 -> CO2}$.',[r'Identifier réactifs et produit.',r'Vérifier la conservation des atomes.'],[r'Réactifs : carbone et dioxygène ; produit : dioxyde de carbone.',r'Un atome de C et deux de O de chaque côté.']),
E('Ajuster l’eau',r'On propose $\ce{H2 + O2 -> H2O}$.',[r'Ajuster les coefficients.',r'Pourquoi ne faut-il pas remplacer \ce{H2O} par \ce{H2O2} ?'],[r'$\ce{2 H2 + O2 -> 2 H2O}$.',r'Changer un indice changerait l’espèce chimique ; l’eau oxygénée n’est pas l’eau.']),
E('Un métal et un acide',r'Le zinc réagit selon $\ce{Zn + 2 H+ -> Zn^{2+} + H2}$.',[r'Quelle espèce gazeuse est produite ?',r'Vérifier la charge totale.'],[r'Le dihydrogène \ce{H2}.',r'À gauche $+2e$, à droite $+2e$ par jeu de coefficients ; la charge est conservée.']),
E('Un effet thermique',r'La température d’un mélange passe de 20,0 à 26,5 °C dans un récipient approximativement isolé.',[r'Quel caractère thermique est suggéré ?',r'Quelle grandeur expérimentale a-t-on suivie ?'],[r'Une transformation exothermique : de l’énergie est cédée au milieu réactionnel et au récipient.',r'La température, mesurée au cours du temps.']),
E('Un premier limitant',r'Pour $\ce{2 H2 + O2 -> 2 H2O}$, on dispose de 0,60 mol de \ce{H2} et 0,20 mol de \ce{O2}.',[r'Déterminer le réactif limitant.',r'Calculer la quantité d’eau formée et le dihydrogène restant.'],[r'$0,60/2=0,30$ ; $0,20/1=0,20$ : le dioxygène limite.',r'0,40 mol d’eau se forment ; $0,60-0,40=\qty{0,20}{mol}$ de \ce{H2} restent.'],'reaction'),
E('Espèces spectatrices',r'On mélange une solution contenant \ce{H+}, \ce{Cl-} et une solution contenant \ce{Na+}, \ce{HO-}. Les ions \ce{Na+} et \ce{Cl-} restent inchangés.',[r'Nommer les espèces spectatrices.',r'Écrire l’équation simplifiée.'],[r'Les ions sodium et chlorure.',r'$\ce{H+ + HO- -> H2O}$.']),
E('Le méthane brûle',r'Une combustion complète consomme 0,150 mol de méthane avec suffisamment de dioxygène.',[r'Écrire l’équation ajustée.',r'Donner les quantités de dioxygène consommé et de dioxyde de carbone produit.'],[r'$\ce{CH4 + 2 O2 -> CO2 + 2 H2O}$.',r'0,300 mol de \ce{O2} sont consommées et 0,150 mol de \ce{CO2} produites.']),
E('Un solide reste',r'Après réaction totale entre du calcaire et un acide, du calcaire reste au fond du récipient.',[r'Quel réactif est en excès ?',r'Quel réactif a limité la transformation, dans le modèle à deux réactifs ?'],[r'Le carbonate de calcium est en excès puisqu’il n’a pas été entièrement consommé.',r'Les ions hydrogène de l’acide ont limité la réaction.']),
E('Détartrer avec des proportions',r'$\ce{CaCO3 + 2 H+ -> Ca^{2+} + CO2 + H2O}$. Quantités initiales : 0,080 mol de calcaire et 0,100 mol de \ce{H+}.',[r'Déterminer le limitant.',r'Calculer le calcaire restant et le \ce{CO2} formé.'],[r'$0,080/1=0,080$ contre $0,100/2=0,050$ : l’acide limite.',r'0,050 mol de calcaire réagissent ; 0,030 mol restent ; 0,050 mol de \ce{CO2} se forment.']),
E('Conserver une masse totale',r'Dans un système fermé, 4,0 g de dihydrogène réagissent totalement avec 32,0 g de dioxygène et ne produisent que de l’eau.',[r'Calculer la masse d’eau produite.',r'Pourquoi une expérience ouverte pourrait-elle sembler perdre de la masse ?'],[r'$m=4,0+32,0=\qty{36,0}{g}$ par conservation de la masse.',r'De la vapeur ou un autre gaz peut quitter le système pesé ; il faut définir le système et contrôler les échanges.']),
E('Une proportion à ne pas confondre',r'Pour $\ce{2 H2 + O2 -> 2 H2O}$, un élève affirme qu’il faut deux grammes de \ce{H2} pour un gramme de \ce{O2}.',[r'Pourquoi son interprétation est-elle fausse ?',r'Donner la proportion correcte avec les quantités de matière.'],[r'Les coefficients ne comparent pas les masses, car les entités n’ont pas la même masse.',r'Il faut deux moles de \ce{H2} pour une mole de \ce{O2}.']),
E('Comparer des essais thermiques',r'Deux essais utilisent le même récipient, le même volume total et le même excès d’un réactif. La quantité du réactif limitant est doublée.',[r'Quel effet peut-on attendre sur l’énergie libérée si la réaction totale reste la même ?',r'Pourquoi la hausse de température mesurée peut-elle s’écarter du double ?'],[r'Le nombre de transformations élémentaires du bilan double ; l’énergie libérée est alors proportionnelle à la quantité du limitant.',r'Les pertes thermiques, le temps de mesure et les échanges avec le récipient peuvent changer le résultat observé.'])],
E('Choisir le bon mélange',r'On veut produire exactement 0,300 mol d’eau par $\ce{2 H2 + O2 -> 2 H2O}$, sans réactif restant.',[r'Déterminer les quantités initiales nécessaires.',r'On introduit en réalité 0,300 mol de chaque gaz : calculer l’état final.',r'Comparer la quantité d’eau obtenue dans les deux cas.'],[r'Il faut 0,300 mol de \ce{H2} et 0,150 mol de \ce{O2}.',r'$0,300/2<0,300/1$ : \ce{H2} limite. Il se forme 0,300 mol d’eau et il reste 0,150 mol de \ce{O2}.',r'La quantité d’eau est identique ; le deuxième mélange gaspille un excès de dioxygène.'],methode=r'Piste 1 : lire les rapports des coefficients. Piste 2 : calculer la consommation d’oxygène. Piste 3 : faire un bilan final.',note=r'Une quantité de produit visée ne suffit pas à garantir des proportions stœchiométriques ; il faut régler les deux réactifs.'),
['Réactifs, produits, spectateurs','Conservation des éléments et de la charge','Cinq familles de réactions usuelles','Stœchiométrie et réactif limitant','Effet thermique et masse du limitant'])

C('Synthétiser et identifier','synthese',[
'Expliquer l’intérêt d’un chauffage à reflux.',
'Légender les montages nécessaires à une synthèse.',
'Comparer une espèce synthétisée à une espèce naturelle.'],[
('Une espèce et son origine',r'''Une synthèse fabrique une espèce à partir d'autres espèces par transformation chimique. Une espèce présente dans la nature peut être préparée au laboratoire. Si les molécules sont identiques, leurs propriétés intrinsèques sont les mêmes, quelle que soit l'origine ; les échantillons peuvent néanmoins différer par leurs impuretés.
\begin{attention}[Naturel ne signifie pas sans danger]L'origine d'un échantillon ne suffit pas à juger sa dangerosité, sa pureté ou son impact environnemental. Lire les données et les pictogrammes de sécurité de chaque produit.\end{attention}'''),
('Chauffer sans perdre le milieu',r'''Le chauffage à reflux chauffe un mélange tout en condensant les vapeurs dans un réfrigérant vertical. Le liquide condensé retombe dans le ballon : on limite les pertes d'espèces volatiles. Le réfrigérant reste ouvert vers l'atmosphère ; l'eau entre par le bas et sort par le haut.
\schema{reflux}
Le montage est maintenu par un support. Des grains anti-bouillonnement peuvent régulariser l'ébullition si le protocole le prévoit ; ils se mettent avant le chauffage. Le reflux ne sépare pas, à lui seul, le produit des autres espèces.'''),
('Isoler et contrôler',r'''Après réaction, le protocole peut prévoir une séparation, un lavage ou une filtration, puis une identification. Une chromatographie compare produit synthétisé et références sur la même plaque, dans le même éluant.
\schema{ccm-synthese}
\begin{savoirfaire}[Argumenter]Dire quelles taches se correspondent ; rechercher des taches supplémentaires ; conclure prudemment sur l'identité et la pureté dans les limites de la méthode. Une seule tache ne prouve pas l'absence de toute impureté non détectée.\end{savoirfaire}''')],
r'''\begin{experience}[Concevoir un compte rendu de synthèse]À partir d'un protocole fourni par l'enseignant, préparer le schéma légendé du reflux et la fiche de sécurité, identifier les étapes de transformation, d'isolement et de contrôle. Comparer ensuite par CCM le produit obtenu et une référence. Ne réaliser aucune synthèse domestique à partir du seul schéma du livre.\end{experience}''',[
E('L’origine d’une molécule',r'Une molécule de vanilline synthétisée a la même structure que celle extraite de la vanille.',[r'Constituent-elles la même espèce chimique ?',r'Les deux échantillons sont-ils nécessairement de même composition ?'],[r'Oui, si les entités sont identiques, il s’agit de la même espèce.',r'Non : un extrait naturel peut contenir beaucoup d’autres espèces ; un produit synthétique peut aussi présenter des impuretés.']),
E('Reconnaître le reflux',r'Observer le montage fourni.',[r'Nommer le ballon, le réfrigérant et le chauffage.',r'Indiquer le sens de circulation de l’eau.'],[r'Le ballon contient le mélange ; le réfrigérant vertical condense les vapeurs ; le chauffe-ballon apporte de l’énergie.',r'L’eau entre en bas et sort en haut pour remplir efficacement la gaine.'],'reflux'),
E('Le rôle du réfrigérant',r'Un mélange contient un solvant volatil et doit être chauffé.',[r'Pourquoi utiliser un reflux ?',r'Le réfrigérant empêche-t-il toute transformation chimique ?'],[r'Il condense les vapeurs qui retournent dans le ballon et limite les pertes de matière.',r'Non : la transformation se déroule dans le mélange chauffé ; le réfrigérant agit surtout sur les vapeurs.']),
E('Une cuve de CCM',r'La ligne de dépôt est située à 1 cm du bas d’une plaque. L’éluant atteint 0,5 cm dans la cuve.',[r'La position du dépôt convient-elle ?',r'Que risquerait-on si l’éluant atteignait 1,5 cm ?'],[r'Oui, le dépôt est au-dessus du niveau initial de l’éluant.',r'Les dépôts pourraient se dissoudre directement dans le bain et quitter la plaque.']),
E('Comparer deux produits',r'Les pistes N et S représentent une référence naturelle et un échantillon synthétisé ; R est un réactif de départ.',[r'Quel indice associe S à l’espèce N ?',r'Quel indice révèle une impureté de S ?'],[r'Une tache de S est à la même hauteur que la tache de N dans les mêmes conditions.',r'Une seconde tache de S correspond à R : le réactif de départ est encore détecté.'],'ccm-synthese'),
E('Un montage à corriger',r'Un élève ferme hermétiquement le haut du réfrigérant et branche l’arrivée d’eau en haut.',[r'Corriger les deux choix.',r'Pourquoi le premier présente-t-il un risque ?'],[r'Laisser une communication avec l’atmosphère et faire entrer l’eau en bas, sortir en haut.',r'Chauffer un système fermé peut provoquer une surpression.']),
E('Étapes d’un protocole',r'Un protocole indique : chauffer à reflux, laisser refroidir, filtrer, analyser le solide par CCM après dissolution adaptée.',[r'Associer transformation, isolement et contrôle à ces étapes.',r'Pourquoi le refroidissement précède-t-il la manipulation suivante ?'],[r'Reflux : transformation ; filtration : isolement d’un solide ; CCM : contrôle.',r'Il réduit le risque lié à la chaleur et peut permettre la formation du solide recherché, selon le protocole.']),
E('Une seule tache',r'Un produit présente une seule tache visible sur une CCM.',[r'Quelle conclusion limitée peut-on formuler ?',r'Peut-on affirmer une pureté absolue ?'],[r'Une seule espèce est détectée avec cette méthode et ces conditions.',r'Non : deux espèces peuvent migrer ensemble, ou une impureté ne pas être révélée.']),
E('Un test d’identité incomplet',r'Une espèce synthétisée et une référence ont la même masse volumique à la précision de la mesure.',[r'Est-ce une preuve suffisante ?',r'Proposer deux contrôles complémentaires.'],[r'Non : différentes compositions peuvent donner des masses volumiques proches.',r'Une CCM dans les mêmes conditions et une température de changement d’état, si ces méthodes conviennent aux produits.']),
E('Légender utilement',r'Un schéma de reflux ne porte que les noms « tube » et « pot ».',[r'Pourquoi les légendes sont-elles insuffisantes ?',r'Quelles informations de fonctionnement faut-il ajouter ?'],[r'Elles n’identifient ni le réfrigérant, ni le ballon, ni les fonctions des éléments.',r'Le chauffage, le mélange, l’entrée et la sortie d’eau, ainsi que le retour des condensats et l’ouverture vers l’atmosphère.'],'reflux'),
E('Une comparaison équitable',r'Deux CCM ont été réalisées dans des éluants différents. Une tache a la même hauteur sur les deux plaques.',[r'Peut-on en déduire une identité ?',r'Proposer une comparaison plus fiable.'],[r'Non : la migration dépend de l’éluant et du support, ainsi que de la hauteur du front.',r'Déposer échantillon et référence sur une même plaque et développer ensemble.']),
E('Limiter l’impact',r'Deux protocoles produisent la même espèce en quantité comparable. A utilise 100 mL d’un solvant à risque ; B en utilise 20 mL d’un solvant moins dangereux selon les fiches fournies.',[r'Quel choix paraît préférable sur ces critères ?',r'Pourquoi faut-il garder d’autres critères dans l’analyse ?'],[r'B réduit ici le volume et la dangerosité annoncée du solvant.',r'Il faut aussi examiner l’énergie, les déchets, la quantité réellement obtenue et les conditions de sécurité.'])],
E('Le produit est-il prêt ?',r'La CCM du produit synthétisé S présente une tache correspondant au produit naturel N et une autre correspondant au réactif R.',[r'Peut-on conclure que la synthèse a formé l’espèce recherchée ?',r'Peut-on livrer S comme espèce pure sur cette seule analyse ?',r'Proposer une stratégie de contrôle après purification.'],[r'La tache commune avec N soutient cette hypothèse ; compléter l’identification si nécessaire.',r'Non : une autre espèce est détectée, compatible avec du réactif restant.',r'Après une purification adaptée au protocole, refaire une CCM avec S, N et R sur la même plaque. La disparition de la tache de R appuie l’amélioration de la pureté.'],'ccm-synthese',methode=r'Piste 1 : séparer identité et pureté. Piste 2 : attribuer chaque tache. Piste 3 : proposer un contrôle comparable.',note=r'Identifier le produit recherché et vérifier sa pureté sont deux étapes distinctes.'),
['Naturel et synthétique','Montage à reflux légendé','CCM légendée et comparaison','Isolement et contrôle','Sécurité et environnement'])

C('Transformations nucléaires','radioactivite',[
'Reconnaître des isotopes à leur noyau.',
'Distinguer transformation physique, chimique et nucléaire.',
'Associer fusion et fission aux conversions d’énergie.'],[
('Même élément, noyaux différents',r'''Des isotopes possèdent le même nombre de protons $Z$ et des nombres de neutrons différents. Ils appartiennent au même élément chimique, mais leurs nombres de masse $A$ diffèrent.
\begin{exemple}Les noyaux $\ce{^{12}_{6}C}$ et $\ce{^{14}_{6}C}$ possèdent tous deux six protons, mais respectivement six et huit neutrons. Ils sont isotopes. Tous les isotopes ne sont pas radioactifs.\end{exemple}'''),
('Le noyau se transforme',r'''Une transformation physique conserve les espèces ; une transformation chimique redistribue les atomes entre espèces sans modifier leurs noyaux ; une transformation nucléaire modifie des noyaux. Dans les équations nucléaires simples du livre, les sommes des nombres $A$ et des nombres $Z$ se conservent.
\schema{nucleaire}
\begin{savoirfaire}[Lire une équation]Identifier les noyaux de départ et d'arrivée ; vérifier séparément les sommes de $A$ et de $Z$. Un neutron s'écrit $\ce{^{1}_{0}n}$. Une équation de fusion ou de fission peut comporter d'autres produits, comme des rayonnements, qui ne sont pas dessinés dans un modèle simplifié.\end{savoirfaire}'''),
('Fusion, fission et énergie',r'''La fusion assemble des noyaux légers ; la fission scinde un noyau lourd. Le Soleil convertit de l'énergie au cours de transformations nucléaires dont le bilan transforme de l'hydrogène en hélium. Dans une centrale actuelle à fission, la fission de noyaux lourds apporte de l'énergie thermique ; une chaîne de conversions permet ensuite de produire de l'électricité.
\begin{attention}La fusion nucléaire n'est pas la fusion d'un solide. Le même mot désigne ici une modification du noyau ; dans le changement d'état, les noyaux et les espèces restent inchangés.\end{attention}
On compare des bilans énergétiques fournis sans imposer ici la relation entre masse et énergie ni une loi de décroissance radioactive.''')],
r'''\begin{experience}[Modéliser des bilans]Avec des jetons de deux couleurs représentant protons et neutrons, vérifier une équation fournie. Le modèle contrôle les nombres ; il ne simule ni les mécanismes, ni les conditions de déclenchement, ni la probabilité des réactions. Les études nucléaires du manuel sont documentaires, sans manipulation de source radioactive.\end{experience}''',[
E('Reconnaître des isotopes',r'On donne $\ce{^{16}_{8}O}$, $\ce{^{18}_{8}O}$ et $\ce{^{19}_{9}F}$.',[r'Quels noyaux sont isotopes ?',r'Donner leurs nombres de neutrons.'],[r'Les deux noyaux d’oxygène ont le même $Z=8$ et des $A$ différents.',r'Ils possèdent 8 et 10 neutrons. Le fluor en possède 10, mais son $Z$ est différent.']),
E('Classer des transformations',r'On observe une vaporisation, une combustion et une fission.',[r'Associer physique, chimique et nucléaire.',r'Laquelle change la nature de certains noyaux ?'],[r'Vaporisation : physique ; combustion : chimique ; fission : nucléaire.',r'La fission.']),
E('Un neutron',r'Le neutron est noté $\ce{^{1}_{0}n}$.',[r'Interpréter les nombres 1 et 0.',r'Quelle est sa charge électrique ?'],[r'Il compte pour un nucléon et pour zéro proton.',r'Sa charge électrique est nulle.']),
E('La fusion de la glace',r'Un texte affirme que faire fondre un glaçon est une réaction nucléaire de fusion.',[r'Corriger cette phrase.',r'Les molécules d’eau sont-elles transformées en une autre espèce ?'],[r'C’est une transformation physique, un changement d’état solide-liquide.',r'Non, elles restent des molécules de \ce{H2O}.']),
E('Une fusion fournie',r'$\ce{^{2}_{1}H + ^{3}_{1}H -> ^{4}_{2}He + ^{1}_{0}n}$.',[r'Vérifier les deux bilans.',r'Pourquoi s’agit-il d’une fusion nucléaire ?'],[r'$A : 2+3=4+1=5$ ; $Z : 1+1=2+0=2$.',r'Deux noyaux légers donnent un noyau plus lourd, avec émission d’un neutron.'],'nucleaire'),
E('Compléter une fission',r'$\ce{^{235}_{92}U + ^{1}_{0}n -> ^{141}_{56}Ba + ^{92}_{36}Kr + x ^{1}_{0}n}$.',[r'Déterminer $x$ par conservation de $A$.',r'Contrôler la somme de $Z$.'],[r'$235+1=141+92+x$, donc $x=3$.',r'$92=56+36$ ; les neutrons n’ajoutent pas de charge.']),
E('La source d’énergie du Soleil',r'Le Soleil émet de l’énergie pendant des milliards d’années.',[r'À quelle famille de transformations cette énergie est-elle reliée ?',r'Pourquoi une combustion chimique est-elle un autre modèle ?'],[r'À des transformations nucléaires de fusion dont le bilan convertit de l’hydrogène en hélium.',r'Une combustion réorganise les atomes sans transformer les noyaux ; ce n’est pas le mécanisme énergétique principal du Soleil.']),
E('Une chaîne de conversions',r'Une centrale à fission fournit de l’électricité.',[r'Compléter : nucléaire vers thermique vers mouvement vers électrique.',r'Pourquoi toute l’énergie ne devient-elle pas électrique ?'],[r'Les réactions chauffent un fluide ; un dispositif met en mouvement une turbine entraînant un alternateur.',r'Une part est transférée à l’environnement ; les conversions ne dirigent pas toute l’énergie vers la sortie électrique utile.']),
E('Un noyau inconnu',r'$\ce{^{14}_{7}N + ^{4}_{2}He -> ^{17}_{8}O + X}$.',[r'Déterminer $A$ et $Z$ de X.',r'Identifier X parmi proton, neutron et noyau d’hélium.'],[r'$A_X=14+4-17=1$ ; $Z_X=7+2-8=1$.',r'X est un proton, noyau $\ce{^{1}_{1}H}$.']),
E('Un bilan énergétique fourni',r'Une réaction donnée libère $3,2\times10^{-11}$ J par événement. Il se produit $2,0\times10^{18}$ événements.',[r'Calculer l’énergie totale.',r'Quelle hypothèse permet la multiplication ?'],[r'$E=3,2\times10^{-11}\times2,0\times10^{18}=\qty{6,4e7}{J}$.',r'Chaque événement est supposé libérer la même énergie dans le bilan choisi.']),
E('Charge et nucléons',r'Une équation proposée conserve $A$ mais transforme un noyau de $Z=10$ en deux noyaux de $Z=4$ et $Z=5$, sans autre particule chargée.',[r'Quel bilan pose problème ?',r'Pourquoi un seul bilan correct ne suffit-il pas ?'],[r'La charge : $10\neq4+5$.',r'Il faut respecter simultanément les lois de conservation adaptées à toutes les particules de l’équation.']),
E('Isotopes et ions',r'On compare $\ce{^{23}_{11}Na}$ et $\ce{^{23}_{11}Na+}$.',[r'S’agit-il de deux isotopes différents ?',r'Qu’est-ce qui diffère entre les deux entités ?'],[r'Non : leur noyau est le même, avec les mêmes $A$ et $Z$.',r'L’ion a un électron de moins. Une ionisation concerne le cortège électronique.'])],
E('Auditer une réaction',r'On propose $\ce{^{235}_{92}U + ^{1}_{0}n -> ^{140}_{54}Xe + ^{94}_{38}Sr + x ^{1}_{0}n}$. Chaque événement libère ici $3,0\times10^{-11}$ J, valeur fournie pour l’exercice.',[r'Trouver $x$ et vérifier la charge.',r'Nommer la famille de transformation.',r'Combien d’événements faut-il pour libérer \qty{9,0e7}{J} ?'],[r'$x=236-140-94=2$ ; $92=54+38$.',r'Une fission : un noyau lourd donne deux noyaux de tailles plus petites.',r'$N=9,0\times10^7/(3,0\times10^{-11})=\num{3,0e18}$ événements.'],methode=r'Piste 1 : deux bilans indépendants. Piste 2 : comparer les tailles des noyaux. Piste 3 : énergie totale divisée par énergie par événement.',note=r'Une équation nucléaire s’analyse par les noyaux et les conservations, pas par une combustion ordinaire.'),
['Isotopes','Écriture de réactions nucléaires','Fusion et fission','Soleil et centrales','Distinguer trois transformations'])
